package com.pulsepay.webhook;
import java.net.URI; import java.net.http.*; import java.nio.charset.StandardCharsets; import java.time.*; import java.util.*; import javax.crypto.Mac; import javax.crypto.spec.SecretKeySpec; import org.springframework.beans.factory.annotation.Value; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional;
@Component public class WebhookDeliveryWorker { private final JdbcTemplate db; private final SecretCrypto crypto; private final int maxAttempts; private final HttpClient http=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(5)).build(); public WebhookDeliveryWorker(JdbcTemplate db,SecretCrypto crypto,@Value("${pulsepay.webhook.max-attempts:6}")int maxAttempts){this.db=db;this.crypto=crypto;this.maxAttempts=Math.max(1,maxAttempts);} @Scheduled(fixedDelay=2000) @Transactional public void deliver(){var jobs=db.query("select d.id,d.event_id,d.event_type,d.payload,d.attempts,w.url,w.secret_encrypted from webhook_deliveries d join webhook_endpoints w on w.id=d.webhook_endpoint_id where d.status in ('PENDING','RETRYING') and (d.next_attempt_at is null or d.next_attempt_at<=now()) order by d.created_at limit 20 for update skip locked",(rs,i)->new Object[]{UUID.fromString(rs.getString(1)),rs.getString(2),rs.getString(3),rs.getString(4),rs.getInt(5),rs.getString(6),rs.getString(7)});for(Object[] j:jobs){int attempt=(Integer)j[4]+1;try{String ts=Long.toString(Instant.now().getEpochSecond()),signature=hmac(crypto.decrypt((String)j[6]),ts+"."+j[3]);HttpRequest req=HttpRequest.newBuilder(WebhookUrlValidator.publicHttpsUri((String)j[5])).timeout(Duration.ofSeconds(10)).header("Content-Type","application/json").header("PulsePay-Signature","t="+ts+",v1="+signature).header("PulsePay-Event-Id",(String)j[1]).POST(HttpRequest.BodyPublishers.ofString((String)j[3])).build();int code=http.send(req,HttpResponse.BodyHandlers.discarding()).statusCode();if(code>=200&&code<300)db.update("update webhook_deliveries set status='SUCCEEDED',attempts=?,last_http_status=?,updated_at=now() where id=?",attempt,code,j[0]);else fail(j,attempt,code);}catch(Exception e){fail(j,attempt,null);}}} private void fail(Object[] j,int attempt,Integer code){if(attempt>=maxAttempts)db.update("update webhook_deliveries set status='DEAD_LETTER',attempts=?,last_http_status=?,updated_at=now() where id=?",attempt,code,j[0]);else db.update("update webhook_deliveries set status='RETRYING',attempts=?,last_http_status=?,next_attempt_at=now()+(interval '1 second' * ?),updated_at=now() where id=?",attempt,code,1<<Math.min(attempt,8),j[0]);} private String hmac(String secret,String s)throws Exception{Mac m=Mac.getInstance("HmacSHA256");m.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));return HexFormat.of().formatHex(m.doFinal(s.getBytes(StandardCharsets.UTF_8)));}}
